(() => {
  (typeof ngDevMode === "undefined" || ngDevMode) && setClassMetadata(ContratsForm, [{
    type: Component,
    args: [{ selector: "app-contrats-form", standalone: false, template: `<div class="page-container">\r
  <div class="page-header">\r
    <div class="header-left">\r
      <button mat-icon-button (click)="cancel()">\r
        <mat-icon>arrow_back</mat-icon>\r
      </button>\r
      <div>\r
        <h1 class="page-title">Nouveau Contrat</h1>\r
        <div class="page-subtitle">Renseignez les informations du contrat</div>\r
      </div>\r
    </div>\r
  </div>\r
\r
  <div class="page-content">\r
    <form [formGroup]="form" class="form-container">\r
      <mat-card class="form-card">\r
        <mat-card-header>\r
          <div mat-card-avatar class="card-icon">\r
            <mat-icon>article</mat-icon>\r
          </div>\r
          <mat-card-title>Informations G\xE9n\xE9rales</mat-card-title>\r
        </mat-card-header>\r
\r
        <mat-card-content>\r
          <div class="form-grid">\r
            <!-- Employ\xE9 -->\r
            <mat-form-field appearance="outline">\r
              <mat-label>Employ\xE9 concern\xE9</mat-label>\r
              <mat-select formControlName="employe">\r
                <mat-option value="">\u2014 Aucun \u2014</mat-option>\r
                <div style="padding: 6px 12px; border-bottom: 1px solid #e0e0e0; display: flex; align-items: center; background: #fafafa;">\r
                  <mat-icon style="color: #888; margin-right: 8px; font-size: 20px; width: 20px; height: 20px;">search</mat-icon>\r
                  <input matInput placeholder="Rechercher un employ\xE9..." \r
                         formControlName="employeSearch" \r
                         (keydown)="$event.stopPropagation()"\r
                         style="width: 100%; border: none; outline: none; font-size: 14px; background: transparent;">\r
                </div>\r
                @for (emp of filteredEmployees$ | async; track emp.id) {\r
                  <mat-option [value]="emp.prenom + ' ' + emp.nom">{{ emp.prenom }} {{ emp.nom }} ({{ emp.matricule }})</mat-option>\r
                }\r
              </mat-select>\r
            </mat-form-field>\r
 \r
            <!-- Service -->\r
            <mat-form-field appearance="outline">\r
              <mat-label>Service</mat-label>\r
              <mat-select formControlName="service">\r
                <mat-option value="">\u2014 Aucun \u2014</mat-option>\r
                @for (srv of services$ | async; track srv.code) {\r
                  <mat-option [value]="srv.libelle">{{ srv.libelle }}</mat-option>\r
                }\r
              </mat-select>\r
            </mat-form-field>\r
 \r
            <!-- Type -->\r
            <mat-form-field appearance="outline">\r
              <mat-label>Type de Contrat</mat-label>\r
              <mat-select formControlName="type">\r
                <mat-option value="">\u2014 Aucun \u2014</mat-option>\r
                @for (t of contrats$ | async; track t.code) {\r
                  <mat-option [value]="t.libelle">{{ t.libelle }}</mat-option>\r
                }\r
              </mat-select>\r
            </mat-form-field>\r
 \r
            <!-- Statut -->\r
            <mat-form-field appearance="outline">\r
              <mat-label>Statut</mat-label>\r
              <mat-select formControlName="statut">\r
                <mat-option value="">\u2014 Aucun \u2014</mat-option>\r
                @for (s of statuts; track s) {\r
                  <mat-option [value]="s">{{ s }}</mat-option>\r
                }\r
              </mat-select>\r
            </mat-form-field>\r
 \r
            <!-- Date D\xE9but -->\r
            <mat-form-field appearance="outline">\r
              <mat-label>Date de d\xE9but</mat-label>\r
              <input matInput [matDatepicker]="startPicker" formControlName="dateDebut">\r
              <mat-datepicker-toggle matIconSuffix [for]="startPicker"></mat-datepicker-toggle>\r
              <mat-datepicker #startPicker></mat-datepicker>\r
            </mat-form-field>\r
 \r
            <!-- Date Fin -->\r
            <mat-form-field appearance="outline">\r
              <mat-label>Date de fin</mat-label>\r
              <input matInput [matDatepicker]="endPicker" formControlName="dateFin">\r
              <mat-datepicker-toggle matIconSuffix [for]="endPicker"></mat-datepicker-toggle>\r
              <mat-datepicker #endPicker></mat-datepicker>\r
            </mat-form-field>\r
 \r
          </div>\r
        </mat-card-content>\r
      </mat-card>\r
\r
      <div class="form-actions">\r
        <button mat-button type="button" (click)="cancel()">Annuler</button>\r
        <button mat-flat-button color="primary" type="button" (click)="save()" [disabled]="form.invalid || saving">\r
          <mat-icon *ngIf="!saving">save</mat-icon>\r
          <span>{{ saving ? 'Enregistrement...' : 'Enregistrer' }}</span>\r
        </button>\r
      </div>\r
\r
    </form>\r
  </div>\r
</div>\r
` }]
  }], () => [{ type: FormBuilder }, { type: Router }, { type: ModuleNavService }, { type: ContratService }, { type: DbRefService }, { type: EmployeeService }], null);
})();
